// P1 防御：校验 webhook 密钥。
// 优先 Authorization: Basic base64(taskfin:<secret>) 头（推荐，密钥不进 URL/日志）；
// 兼容历史 ?secret= 查询参数（过渡期保留，配置 Vikunja Basic Auth 后从 URL 移除即可）。
const expected = (typeof $vars !== 'undefined' && $vars && $vars.webhook_secret) ? $vars.webhook_secret : '';
if (!expected) return [];
const h = ($input.item.json && $input.item.json.headers) || {};
const authHeader = h['authorization'] || h['Authorization'] || '';
const expectedBasic = 'Basic ' + Buffer.from('taskfin:' + expected).toString('base64');
if (authHeader && authHeader === expectedBasic) return $input.all();
const q = ($input.item.json && $input.item.json.query) || {};
const got = q.secret || '';
if (got && got === expected) return $input.all();
return [];

// 任务新建时，把 fund: 金额登记为「预算」（仅在 Vikunja 留痕，不写 ezB 真实支出）。
// A1：预算/计划支出只作可见跟踪，不落 type=3，避免与「完成时记账」重复扣款（见 P2）。
const e = $input.item.json;
if (e.event_name && e.event_name !== 'task.created') return [];
const task = (e.data && e.data.task) ? e.data.task : {};
const labels = (task.labels || []).map(l => (l.title || l).toString());
const m = labels.find(x => x.startsWith('fund:'));
if (!m) return [];
const parts = m.slice(5).split(':');
const amount = parseFloat(parts[0]);
if (Number.isNaN(amount)) return [];
const currency = parts[1] || 'CNY';
const account = parts[2] || 'cash';
return [{
  json: {
    taskId: task.id,
    title: task.title,
    fund_amount: amount,
    fund_currency: currency,
    fund_account: account,
    is_recur: labels.includes('recur')
  }
}];
